CREATE TABLE public.pipeline_projects (
  id TEXT NOT NULL PRIMARY KEY,
  data JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()
);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.pipeline_projects TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.pipeline_projects TO anon;
GRANT ALL ON public.pipeline_projects TO service_role;
ALTER TABLE public.pipeline_projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY "allow all select" ON public.pipeline_projects FOR SELECT TO public USING (true);
CREATE POLICY "allow all insert" ON public.pipeline_projects FOR INSERT TO public WITH CHECK (true);
CREATE POLICY "allow all update" ON public.pipeline_projects FOR UPDATE TO public USING (true) WITH CHECK (true);
CREATE POLICY "allow all delete" ON public.pipeline_projects FOR DELETE TO public USING (true);

